//! E8 gate: 50 standard vectors (ARC-721/1155 + `.aura` names +
//! identity) and the first DAO vote through the UI (ECOSYSTEM_PLAN E8).
//!
//! The fixture `tests/fixtures/e8-standards.txt` is the golden oracle
//! (generated by `tools/gen_e8_vectors.py`): every vector pins its
//! status — `ok` or an exact `E8: …` error literal — plus post-state
//! reads. This test executes all 50 against [`NftWorld`] and rebuilds
//! the vectors digest; the independent Python model
//! `tools/e8_nft_check.py` must produce the same digest.
//!
//! The DAO gate runs [`run_e8_scenario`]: proposal 1 with the first vote
//! cast through the UI, a rejected double vote, finalization and
//! execution after the timelock.

use aura_storage::dao_ui::{DaoUi, run_e8_scenario, scenario_digest};
use aura_storage::governance::{ProposalState, Support, T6_VETO_SUNSET_BLOCK};
use aura_storage::issuance::ALCRY;
use aura_storage::nft::{E8Error, GRACE_DAYS, NftWorld, TERM_DAYS};

const FIXTURE: &str = include_str!("fixtures/e8-standards.txt");
const VECTORS_DIGEST: &str = "8cb9da945b0eed8f4432d31b71d20fffb72a6317fc90204d1890bd480c062bd3";
const SCENARIO_DIGEST: &str = "17fd44850375c54c9cf9826b8ed55da0faf1855da72514184c83501f07409d71";
const AGGREGATE_DIGEST: &str = "39674d6a0813cb9beae5837025e1a8b6c00fb8ebe1bc620a06e844a5829fb313";

/// One parsed fixture block.
#[derive(Debug, Default)]
struct Vector {
    id: String,
    op: String,
    args: Vec<(String, String)>,
    status: String,
    err: String,
    reads: Vec<(String, String)>,
}

fn parse_fixture() -> (String, Vec<Vector>) {
    let mut digest = String::new();
    let mut vectors: Vec<Vector> = Vector::default().into_iter_dummy();
    let mut cur: Option<Vector> = None;
    for line in FIXTURE.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (k, v) = line.split_once('=').expect("key=value");
        match k {
            "digest" if cur.is_none() => digest = String::from(v),
            "vector" => {
                if let Some(done) = cur.take() {
                    vectors.push(done);
                }
                cur = Some(Vector {
                    id: String::from(v),
                    ..Vector::default()
                });
            }
            "op" => cur.as_mut().expect("in block").op = String::from(v),
            "status" => cur.as_mut().expect("in block").status = String::from(v),
            "err" => cur.as_mut().expect("in block").err = String::from(v),
            other => {
                let block = cur.as_mut().expect("in block");
                if let Some(read) = other.strip_prefix("read.") {
                    block.reads.push((String::from(read), String::from(v)));
                } else {
                    block.args.push((String::from(other), String::from(v)));
                }
            }
        }
    }
    if let Some(done) = cur.take() {
        vectors.push(done);
    }
    (digest, vectors)
}

/// Tiny helper so `Vector::default().into_iter_dummy()` reads well above.
trait IntoVec {
    fn into_iter_dummy(self) -> Vec<Vector>;
}
impl IntoVec for Vector {
    fn into_iter_dummy(self) -> Vec<Vector> {
        Vec::new()
    }
}

fn arg<'a>(v: &'a Vector, key: &str) -> &'a str {
    v.args
        .iter()
        .find(|(k, _)| k == key)
        .map(|(_, val)| val.as_str())
        .unwrap_or_else(|| panic!("{}: missing arg {key}", v.id))
}

fn run_vector(world: &mut NftWorld, v: &Vector) -> Result<(), E8Error> {
    let a = |key: &str| arg(v, key);
    match v.op.as_str() {
        "mint721" => world.mint721(a("by"), a("to"), a("id").parse().unwrap()),
        "transfer721" => world.transfer721(a("by"), a("id").parse().unwrap(), a("to")),
        "approve721" => world.approve721(a("by"), a("id").parse().unwrap(), a("spender")),
        "transfer_from721" => world.transfer_from721(a("by"), a("id").parse().unwrap(), a("to")),
        "burn721" => world.burn721(a("by"), a("id").parse().unwrap()),
        "read_owner_of" => world.owner_of(a("id").parse().unwrap()).map(|_| ()),
        "mint1155" => world.mint1155(
            a("by"),
            a("to"),
            a("id").parse().unwrap(),
            a("amount").parse().unwrap(),
        ),
        "transfer1155" => world.transfer1155(
            a("frm"),
            a("by"),
            a("id").parse().unwrap(),
            a("to"),
            a("amount").parse().unwrap(),
        ),
        "set_operator" => world.set_operator(a("by"), a("operator"), a("approved") == "true"),
        "transfer_batch1155" => {
            let ids: Vec<u64> = a("ids").split(',').map(|s| s.parse().unwrap()).collect();
            let amounts: Vec<u128> = a("amounts")
                .split(',')
                .map(|s| s.parse().unwrap())
                .collect();
            world.transfer_batch1155(a("frm"), a("by"), a("to"), &ids, &amounts)
        }
        "register_name" => world.register_name(a("by"), a("name"), a("day").parse().unwrap()),
        "renew_name" => world.renew_name(a("name"), a("day").parse().unwrap()),
        "transfer_name" => {
            world.transfer_name(a("by"), a("name"), a("to"), a("day").parse().unwrap())
        }
        "set_target" => {
            world.set_target(a("by"), a("name"), a("target"), a("day").parse().unwrap())
        }
        "resolve" => world
            .resolve(a("name"), a("day").parse().unwrap())
            .map(|_| ()),
        "set_primary" => world.set_primary(a("by"), a("name"), a("day").parse().unwrap()),
        "advance_day" => {
            world.advance_day(a("day").parse().unwrap());
            Ok(())
        }
        "set_identity" => {
            world.set_identity(a("by"), a("name"), a("digest"), a("day").parse().unwrap())
        }
        "clear_identity" => world.clear_identity(a("by"), a("name")),
        "read_identity" => world.identity(a("name")).map(|_| ()),
        other => panic!("unknown op {other}"),
    }
}

fn vectors_digest(vectors: &[Vector]) -> String {
    let mut lines = Vec::new();
    for v in vectors {
        let mut reads = v.reads.clone();
        reads.sort();
        let reads = reads
            .iter()
            .map(|(k, val)| format!("{k}={val}"))
            .collect::<Vec<_>>()
            .join(" ");
        let status = if v.status == "ok" {
            String::from("ok")
        } else {
            format!("err:{}", v.err)
        };
        lines.push(format!("{}|{}|{status}|{reads}", v.id, v.op));
    }
    aura_state::sha256_bytes(lines.join(";").as_bytes()).to_hex()
}

#[test]
fn e8_vectors_all_pass() {
    let (_digest, vectors) = parse_fixture();
    assert_eq!(vectors.len(), 50, "exactly 50 standard vectors");
    let mut world = NftWorld::new();
    for v in &vectors {
        let result = run_vector(&mut world, v);
        match v.status.as_str() {
            "ok" => assert!(
                result.is_ok(),
                "{}: expected ok, got {:?}",
                v.id,
                result.err()
            ),
            "err" => {
                let err = result
                    .expect_err(&format!("{}: expected error", v.id))
                    .to_string();
                assert_eq!(err, v.err, "{}: exact error literal", v.id);
            }
            other => panic!("{}: bad status {other}", v.id),
        }
        for (key, want) in &v.reads {
            assert_eq!(
                &world.query(key),
                want,
                "{}: read {key} after {}",
                v.id,
                v.op
            );
        }
    }
}

#[test]
fn e8_vectors_digest_matches() {
    let (fixture_digest, vectors) = parse_fixture();
    assert_eq!(fixture_digest, VECTORS_DIGEST, "fixture digest pinned");
    assert_eq!(vectors_digest(&vectors), VECTORS_DIGEST, "rebuilt digest");
}

#[test]
fn e8_gate_first_dao_vote_through_ui() {
    let run = run_e8_scenario();
    // The first DAO vote was cast through the UI and recorded.
    assert_eq!(run.first_vote.proposal, 1);
    assert_eq!(run.first_vote.voter, 1);
    assert_eq!(run.first_vote.support, Support::Yes);
    assert_eq!(run.first_vote.power, 150_000 * ALCRY);
    assert_eq!(run.ui_votes, 4);
    // Tallies in raw ALCRY units.
    assert_eq!(run.tally.0, 250_000 * ALCRY, "yes");
    assert_eq!(run.tally.1, 75_000 * ALCRY, "no");
    assert_eq!(run.tally.2, 25_000 * ALCRY, "abstain");
    assert_eq!(run.state, "executed");
}

#[test]
fn e8_gate_scenario_steps_and_digest() {
    let run = run_e8_scenario();
    let expected = [
        "propose|1|proposer=0|created=1000",
        "vote|1|1|yes|150000000000000000000000",
        "vote|1|2|yes|100000000000000000000000",
        "vote|1|3|no|75000000000000000000000",
        "vote|1|4|abstain|25000000000000000000000",
        "vote_err|1|1|E8: vote already cast (1/1)",
        "finalize|1|passed",
        "execute|1|executed",
    ];
    assert_eq!(run.steps, expected, "exact scenario step log");
    assert_eq!(scenario_digest(&run.steps), SCENARIO_DIGEST);
}

#[test]
fn e8_gate_aggregate_digest() {
    // The step log digest is part of the aggregate gate digest.
    let agg = aura_state::sha256_bytes(
        format!(
            "E8|vectors=50|vectors_digest={VECTORS_DIGEST}|\
             scenario_digest={SCENARIO_DIGEST}|first_vote=1/1/yes|\
             ui_votes=4|state=executed"
        )
        .as_bytes(),
    )
    .to_hex();
    assert_eq!(agg, AGGREGATE_DIGEST);
}

#[test]
fn e8_gate_governance_ui_page() {
    let ui = DaoUi::new(
        vec![250_000 * ALCRY, 150_000 * ALCRY],
        ["alice", "bob"].iter().map(|s| String::from(*s)).collect(),
    );
    let html = ui.render_html();
    assert!(html.contains("AuraLite DAO — governance UI"));
    assert!(html.contains("<!doctype html>"));
    // End-to-end: the page shows the vote that went through the UI.
    let mut ui = ui;
    ui.propose(0, 1000).expect("propose");
    ui.vote(1, 1, Support::Yes, 2000).expect("first UI vote");
    let html = ui.render_html();
    assert!(html.contains("Proposal #1"), "proposal card");
    assert!(html.contains("alice"), "proposer label");
    assert!(html.contains("bob"), "voter label");
    assert!(html.contains("150000 ALCRY"), "first-vote power row");
    assert!(html.contains("1 vote receipts"), "receipt footer");
}

// ---------------------------------------------------------- error literals

#[test]
fn e8_nc_literals() {
    // The six mutation-control targets, asserted verbatim.
    let mut w = NftWorld::new();
    w.mint721("root", "alice", 1).unwrap();
    assert_eq!(
        w.mint721("root", "alice", 1).unwrap_err().to_string(),
        "E8: token already exists (1)"
    );
    assert_eq!(
        w.transfer721("carol", 1, "eve").unwrap_err().to_string(),
        "E8: not token owner (carol/1)"
    );
    assert_eq!(
        w.transfer_from721("dave", 1, "dave")
            .unwrap_err()
            .to_string(),
        "E8: not approved (dave/1)"
    );
    w.register_name("alice", "alice.aura", 1).unwrap();
    assert_eq!(
        w.register_name("bob", "alice.aura", 1)
            .unwrap_err()
            .to_string(),
        "E8: name already registered (alice.aura)"
    );
    assert_eq!(
        w.set_identity("bob", "alice.aura", "11", 1)
            .unwrap_err()
            .to_string(),
        "E8: not name owner (bob/alice.aura)"
    );
    let run = run_e8_scenario();
    assert!(
        run.steps
            .iter()
            .any(|s| s == "vote_err|1|1|E8: vote already cast (1/1)"),
        "double vote literal"
    );
}

#[test]
fn e8_dao_error_messages() {
    let k = |n: u128| n * ALCRY;
    // Below threshold.
    let mut ui = DaoUi::new(
        vec![k(5_000), k(250_000)],
        ["alice", "bob"].iter().map(|s| String::from(*s)).collect(),
    );
    assert_eq!(
        ui.propose(0, 1000).unwrap_err().to_string(),
        "E8: below proposal threshold (0)"
    );
    // Unknown proposal.
    assert_eq!(
        ui.vote(99, 1, Support::Yes, 1000).unwrap_err().to_string(),
        "E8: proposal not found (99)"
    );
    let id = ui.propose(1, 1000).unwrap();
    // Zero snapshot power (the flash-stake guard).
    let mut zero = DaoUi::new(
        vec![k(250_000), k(0)],
        ["alice", "bob"].iter().map(|s| String::from(*s)).collect(),
    );
    let zid = zero.propose(0, 1000).unwrap();
    assert_eq!(
        zero.vote(zid, 1, Support::Yes, 1000)
            .unwrap_err()
            .to_string(),
        "E8: no voting power (1)"
    );
    // Voting closed.
    assert_eq!(
        ui.vote(id, 1, Support::Yes, 1_000 + 120_960)
            .unwrap_err()
            .to_string(),
        "E8: voting closed (1)"
    );
    // Finalize while still open.
    assert_eq!(
        ui.finalize(id, 5_000).unwrap_err().to_string(),
        "E8: voting still open (1)"
    );
    ui.vote(id, 1, Support::Yes, 2000).unwrap();
    ui.vote(id, 0, Support::Yes, 3000).unwrap();
    ui.finalize(id, 1_000 + 120_960).unwrap();
    assert_eq!(
        ui.finalize(id, 1_000 + 120_960).unwrap_err().to_string(),
        "E8: proposal already finalized (1)"
    );
    // Timelock.
    assert_eq!(
        ui.execute(id, 1_000 + 120_960).unwrap_err().to_string(),
        "E8: timelock not reached (1)"
    );
    ui.execute(id, 1_000 + 120_960 + 34_560).unwrap();
    assert_eq!(
        ui.execute(id, 1_000 + 120_960 + 34_560)
            .unwrap_err()
            .to_string(),
        "E8: already executed (1)"
    );

    // Not passed (rejection) and veto sunset.
    let mut ui2 = DaoUi::new(
        vec![k(250_000), k(150_000)],
        ["alice", "bob"].iter().map(|s| String::from(*s)).collect(),
    );
    let rid = ui2.propose(0, 1000).unwrap();
    ui2.vote(rid, 1, Support::Yes, 2000).unwrap();
    ui2.vote(rid, 0, Support::No, 3000).unwrap();
    ui2.finalize(rid, 1_000 + 120_960).unwrap();
    assert_eq!(
        ui2.execute(rid, 1_000 + 120_960 + 34_560)
            .unwrap_err()
            .to_string(),
        "E8: not passed (1)"
    );
    // Veto sunsets at T6_VETO_SUNSET_BLOCK (passed proposal required).
    let mut ui3 = DaoUi::new(
        vec![k(250_000), k(150_000)],
        ["alice", "bob"].iter().map(|s| String::from(*s)).collect(),
    );
    let gid = ui3.propose(0, 1000).unwrap();
    ui3.vote(gid, 1, Support::Yes, 2000).unwrap();
    ui3.vote(gid, 0, Support::Yes, 3000).unwrap();
    ui3.finalize(gid, 1_000 + 120_960).unwrap();
    assert_eq!(
        ui3.veto(gid, T6_VETO_SUNSET_BLOCK).unwrap_err().to_string(),
        "E8: veto power has sunset"
    );
}

// ---------------------------------------------------------- metamorphisms

#[test]
fn e8_meta_batch_equals_sequential() {
    let ids = [7u64, 8];
    let amounts = [5u128, 9];
    let mut batch = NftWorld::new();
    let mut seq = NftWorld::new();
    for w in [&mut batch, &mut seq] {
        w.mint1155("root", "alice", 7, 5).unwrap();
        w.mint1155("root", "alice", 8, 9).unwrap();
    }
    batch
        .transfer_batch1155("alice", "alice", "bob", &ids, &amounts)
        .unwrap();
    for (id, amount) in ids.iter().zip(amounts) {
        seq.transfer1155("alice", "alice", *id, "bob", amount)
            .unwrap();
    }
    for (who, id) in [("alice", 7), ("alice", 8), ("bob", 7), ("bob", 8)] {
        assert_eq!(
            batch.balance1155(who, id),
            seq.balance1155(who, id),
            "{who}/{id}"
        );
    }
}

#[test]
fn e8_meta_mint_order_independent() {
    let mut a = NftWorld::new();
    let mut b = NftWorld::new();
    for (to, id) in [("alice", 3u64), ("bob", 1), ("carol", 2)] {
        a.mint721("root", to, id).unwrap();
    }
    for (to, id) in [("carol", 2u64), ("bob", 1), ("alice", 3)] {
        b.mint721("root", to, id).unwrap();
    }
    for id in [1u64, 2, 3] {
        assert_eq!(a.owner_of(id).unwrap(), b.owner_of(id).unwrap());
    }
    assert_eq!(a.supply721(), b.supply721());
}

#[test]
fn e8_meta_vote_order_independent() {
    let k = |n: u128| n * ALCRY;
    let run_votes = |order: [u32; 3]| {
        let mut ui = DaoUi::new(
            vec![k(250_000), k(150_000), k(100_000), k(75_000)],
            ["alice", "bob", "carol", "dave"]
                .iter()
                .map(|s| String::from(*s))
                .collect(),
        );
        let id = ui.propose(0, 1000).unwrap();
        let mut height = 2000;
        for voter in order {
            let support = if voter == 3 {
                Support::No
            } else {
                Support::Yes
            };
            ui.vote(id, voter, support, height).unwrap();
            height += 1000;
        }
        ui.tally(id)
    };
    assert_eq!(run_votes([1, 2, 3]), run_votes([3, 2, 1]));
}

#[test]
fn e8_determinism() {
    let a = run_e8_scenario();
    let b = run_e8_scenario();
    assert_eq!(a.steps, b.steps);
    assert_eq!(scenario_digest(&a.steps), scenario_digest(&b.steps));
    assert_eq!(a.tally, b.tally);
}

// ------------------------------------------------------------- unit surface

#[test]
fn e8_valid_name_rules() {
    assert!(NftWorld::valid_name("alice.aura"));
    assert!(NftWorld::valid_name("a1.aura"));
    assert!(NftWorld::valid_name("a-b-c.aura"));
    assert!(!NftWorld::valid_name("Alice.aura"));
    assert!(!NftWorld::valid_name("-alice.aura"));
    assert!(!NftWorld::valid_name("alice-.aura"));
    assert!(!NftWorld::valid_name("al..aura"));
    assert!(!NftWorld::valid_name("alice.eth"));
    assert!(!NftWorld::valid_name(".aura"));
    assert!(!NftWorld::valid_name(&format!("{}.aura", "a".repeat(33))));
    assert!(NftWorld::valid_name(&format!("{}.aura", "a".repeat(32))));
}

#[test]
fn e8_uri_and_term_constants() {
    let mut w = NftWorld::new();
    assert_eq!(w.uri(5), "none");
    w.set_uri("root", 5, "ipfs://e8").unwrap();
    assert_eq!(w.uri(5), "ipfs://e8");
    assert_eq!(
        w.set_uri("alice", 5, "ipfs://bad").unwrap_err().to_string(),
        "E8: not collection owner (alice)"
    );
    assert_eq!(TERM_DAYS, 365);
    assert_eq!(GRACE_DAYS, 90);
}

#[test]
fn e8_name_lifecycle_constants() {
    // Registration -> expiry boundary -> grace -> re-register, pinned.
    let mut w = NftWorld::new();
    w.register_name("alice", "alice.aura", 1).unwrap();
    assert_eq!(w.name_expiry("alice.aura").unwrap(), 1 + TERM_DAYS);
    assert_eq!(
        w.resolve("alice.aura", 1 + TERM_DAYS + GRACE_DAYS).unwrap(),
        "alice"
    );
    assert_eq!(
        w.resolve("alice.aura", 1 + TERM_DAYS + GRACE_DAYS + 1)
            .unwrap_err()
            .to_string(),
        "E8: name expired (alice.aura)"
    );
    w.register_name("eve", "alice.aura", 1 + TERM_DAYS + GRACE_DAYS + 1)
        .unwrap();
    assert_eq!(w.name_owner("alice.aura").unwrap(), "eve");
    // ProposalState machine covers the DAO states the page renders.
    let _ = ProposalState::Voting;
}
